import itertools
from collections import defaultdict, deque

n = 16

# Define the cycles
cycles = [
    [0, 1, 2, 3, 4],      # C5
    [5, 6, 7, 8, 9],      # C5
    [10, 11, 12, 13, 14, 15]  # C6
]

# Build the complement graph G
edges = set()
for i in range(n):
    for j in range(i+1, n):
        cycle_i = None
        cycle_j = None
        for idx, cyc in enumerate(cycles):
            if i in cyc:
                cycle_i = idx
            if j in cyc:
                cycle_j = idx

        if cycle_i != cycle_j:
            edges.add((i, j))
        else:
            cyc = cycles[cycle_i]
            k = cyc.index(i)
            l = cyc.index(j)
            if (l == (k + 1) % len(cyc)) or (k == (l + 1) % len(cyc)):
                continue
            else:
                edges.add((i, j))

print(f"Number of edges: {len(edges)}")
print(f"Total possible: {n*(n-1)//2}")

# Check degrees
deg = defaultdict(int)
for u, v in edges:
    deg[u] += 1
    deg[v] += 1
print(f"Degree distribution: min={min(deg.values())}, max={max(deg.values())}")
for v in range(n):
    print(f"  deg({v}) = {deg[v]}")

# Check independence number more carefully
def independence_number_exact(graph, n):
    # Use brute force for all subsets up to size 6
    for size in range(6, 0, -1):
        for subset in itertools.combinations(range(n), size):
            is_ind = True
            for i, j in itertools.combinations(subset, 2):
                if (i, j) in graph or (j, i) in graph:
                    is_ind = False
                    break
            if is_ind:
                return size
    return 0

alpha = independence_number_exact(edges, n)
print(f"Independence number: {alpha}")

# Check vertex connectivity
def is_connected(vertices, edge_set):
    if len(vertices) <= 1:
        return True
    adj = defaultdict(set)
    for u, v in edge_set:
        if u in vertices and v in vertices:
            adj[u].add(v)
            adj[v].add(u)
    start = next(iter(vertices))
    visited = set([start])
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                queue.append(v)
    return len(visited) == len(vertices)

# Check kappa by trying subsets of size 4 (for kappa >= 5)
print("Checking if kappa >= 5...")
all_vertices = set(range(n))
kappa_at_least_5 = True
for subset in itertools.combinations(range(n), 4):
    remaining = [v for v in range(n) if v not in subset]
    if not is_connected(remaining, edges):
        print(f"Found disconnecting set of size 4: {subset}")
        kappa_at_least_5 = False
        break

if kappa_at_least_5:
    print("Graph is 5-connected (kappa >= 5)")
else:
    print("Graph is NOT 5-connected")

# Also check kappa >= 6
print("Checking if kappa >= 6...")
kappa_at_least_6 = True
for subset in itertools.combinations(range(n), 5):
    remaining = [v for v in range(n) if v not in subset]
    if not is_connected(remaining, edges):
        print(f"Found disconnecting set of size 5: {subset}")
        kappa_at_least_6 = False
        break

if kappa_at_least_6:
    print("Graph is 6-connected (kappa >= 6)")

